<?php
require_once '../includes/funcoes.php';exigir_admin();
$rows=$pdo->query("SELECT DATE_FORMAT(criado_em,'%Y-%m') mes, SUM(total) receita,COUNT(*) pedidos FROM pedidos WHERE status<>'Cancelado' AND criado_em>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY mes ORDER BY mes")->fetchAll();$labels=[];$vals=[];foreach($rows as $r){$labels[]=date('M/y',strtotime($r['mes'].'-01'));$vals[]=(float)$r['receita'];}
$receita=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM pedidos WHERE status<>'Cancelado' AND MONTH(criado_em)=MONTH(CURDATE()) AND YEAR(criado_em)=YEAR(CURDATE())")->fetchColumn();$pedidos=(int)$pdo->query("SELECT COUNT(*) FROM pedidos WHERE MONTH(criado_em)=MONTH(CURDATE()) AND YEAR(criado_em)=YEAR(CURDATE())")->fetchColumn();$visitas=(int)$pdo->query("SELECT COUNT(*) FROM visitas")->fetchColumn();$ticket=$pedidos?$receita/$pedidos:0;
$titulo='Dashboard — Crescimento';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><div class="section-title"><div class="hero-kicker">Indicadores estratégicos</div><h1>Dashboard de Performance — Crescimento</h1></div>
<div class="row g-3 mb-3"><div class="col-md-6"><div class="metric-card"><div class="metric-label">Faturamento do mês</div><div class="metric-value"><?=preco($receita)?></div></div></div><div class="col-md-6"><div class="metric-card"><div class="metric-label">Ticket médio do mês</div><div class="metric-value"><?=preco($ticket)?></div></div></div></div>
<div class="row g-3"><div class="col-lg-5"><div class="panel mb-3"><h2 class="h5">Receita mensal</h2><div class="chart-wrap"><canvas id="canalChart"></canvas></div></div><div class="panel"><h2 class="h5">Aquisição e conversão</h2><p>Visitas registradas <strong class="float-end"><?=$visitas?></strong></p><p>Pedidos no mês <strong class="float-end"><?=$pedidos?></strong></p><p>Conversão <strong class="float-end"><?=$visitas?number_format($pedidos/$visitas*100,1,',','.'):0?>%</strong></p></div></div>
<div class="col-lg-7"><div class="panel"><h2 class="h5">Crescimento de faturamento (R$)</h2><div class="chart-wrap"><canvas id="crescimentoChart"></canvas></div></div></div></div></section></div>
<script>const labs=<?=json_encode($labels)?>,vals=<?=json_encode($vals)?>;new Chart(document.getElementById('canalChart'),{type:'bar',data:{labels:labs,datasets:[{data:vals,backgroundColor:'#d8c0b7'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}}});new Chart(document.getElementById('crescimentoChart'),{type:'line',data:{labels:labs,datasets:[{label:'Faturamento',data:vals,borderColor:'#bd7778',backgroundColor:'#ead2d1',fill:true,tension:.3}]},options:{responsive:true,maintainAspectRatio:false}});</script>
